sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var _trddetails = current.trade_details;
    var _trdParser = new global.JSON.parse(_trddetails);  //Parse the information in Trade Details field

	//Mapping to corresponding fields from Trade Details is in the below script
    current.transaction_reference = _trdParser.HSBCTransactionIdentification;
    current.owning_business = _trdParser.OwningBusinessName;
    current.cash_hold_indicator = _trdParser.CashHoldIndicator;
    current.script_hold_indicator = _trdParser.ScripHoldIndicator;
    current.same_day_settlement_indicator = _trdParser.SameDaySettlementIndicator;
    current.trade_date = _trdParser.TradeDate;
    current.settlement_date = _trdParser.ExpectedSettlementDate;
    current.settlement_amount_currency = _trdParser.SettlementAmountCurrency;
    current.settlement_amount = _trdParser.SettlementAmount;
    current.settlement_quantity = _trdParser.SettlementQuantity;// testing core issue



})(current, previous);
